{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "Weincludedrandomisedtrials in people with suspected, probable, or confirmed covid-19 that compared blood products and covid-19-specific antiviral antibodies against one another or against no intervention, placebo, or standard care. We included trials regardless of publication status (peer reviewed, in press, or preprint) or language. No restrictions were applied based on severity of illness or setting. For each eligible trial, pairs of reviewers, following training and calibration exercises, extract data independently using a standardised, pilot tested data extraction form. Reviewers collect information on trial characteristics (trial registration, publication status, study status, design), patient characteristics (country, age, sex, smoking habits, comorbidities, setting and type of care, severity of covid-19 symptoms, timing of therapy relative to symptom onset), donor characteristics (selection criteria, sex, severity of disease), and outcomes of interest (means or medians and measures of variability for continuous outcomes and the number of participants analysedandthenumberofparticipantswhoexperiencedanevent for dichotomous outcomes).",
      "reason": "The eligibility criteria specify the study design (randomised trials), population (suspected/probable/confirmed COVID-19), interventions/comparators (blood products and antiviral antibodies compared with each other or against no intervention/placebo/standard care), and explicitly state no restrictions by severity or setting; outcome follow-up/timing is also described elsewhere in the same evidence (e.g., closest to 90 days, within 28 days, closest to 7 days ±3 days)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "We included trials regardless of publication status (peer reviewed, in press, or preprint) or language.",
      "reason": "The review specifies eligibility with respect to publication status and language. (Dissemination year is not explicitly stated in the provided evidence, but the required characteristics regarding language and report/publication status are present.)"
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided that the review distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_15",
      "quote": "Weincludedrandomisedtrials in people with suspected, probable, or confirmed covid-19 that compared blood products and covid-19-specific antiviral antibodies against one another or against no intervention, placebo, or standard care. Randomised trials evaluating drug treatments 11 and prophylaxis 12 for covid-19 were synthesised in separate living network meta-analyses.",
      "reason": "The evidence indicates how comparisons are structured (antibody therapies/blood products compared with each other or against no intervention/placebo/standard care) and that there are separate syntheses for drug treatments vs prophylaxis. However, it does not clearly specify the groups used in each synthesis in a way that is explicitly linked to comparison groupings defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale is provided in the retrieved evidence for any notable restrictions on study eligibility."
    }
  ],
  "confidence": 62
}

